css:
.uip { background: var(--card); border: 1px solid color-mix(in srgb, var(--ink) 8%, transparent); border-radius: var(--radius-card); padding: 22px; box-shadow: 0 30px 70px -30px color-mix(in srgb, var(--ink) 35%, transparent); color: var(--ink); font-family: var(--font-body); }
.uip__tag { display: flex; justify-content: space-between; align-items: center; gap: 12px; margin: 0 0 14px; font: 700 12.5px/1.3 var(--font-body); letter-spacing: .04em; color: var(--accent); }
.uip__meta { color: var(--muted); font-weight: 600; letter-spacing: 0; }
.uip__title { font: 700 18px/1.35 var(--font-heading); margin: 0 0 14px; }
.uip__rows { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 8px; }
.uip__row { display: flex; justify-content: space-between; align-items: baseline; gap: 14px; padding: 11px 14px; border-radius: 12px; background: var(--paper); font-size: 14.5px; }
.uip__l { color: var(--muted); font-weight: 600; }
.uip__v { font-weight: 800; text-align: right; color: var(--ink); }
.uip__row.is-accent { background: color-mix(in srgb, var(--accent) 10%, var(--card)); }
.uip__row.is-accent .uip__l { color: var(--ink); }
.uip__row.is-accent .uip__v { color: var(--accent); }
.uip__note { margin: 14px 0 0; padding: 12px 14px; border-radius: 12px; background: color-mix(in srgb, var(--volt, #FFD23F) 22%, var(--card)); font-size: 14px; font-weight: 600; line-height: 1.5; }
.uip--dark { background: rgb(255 255 255 / .06); border-color: rgb(255 255 255 / .12); box-shadow: none; color: #fff; }
.uip--dark .uip__tag { color: var(--volt, #FFD23F); }
.uip--dark .uip__row { background: rgb(255 255 255 / .06); }
.uip--dark .uip__l { color: rgb(255 255 255 / .62); }
.uip--dark .uip__v { color: #fff; }
.uip--dark .uip__row.is-accent { background: rgb(255 210 63 / .14); }
.uip--dark .uip__row.is-accent .uip__l, .uip--dark .uip__row.is-accent .uip__v { color: var(--volt, #FFD23F); }
.uip--dark .uip__note { background: rgb(255 255 255 / .08); color: #fff; }
.uip--chip { display: inline-flex; flex-direction: column; gap: 2px; padding: 12px 16px; border-radius: 16px; }
.uip--chip .uip__tag { margin: 0; color: var(--muted); font-size: 12px; }
.uip--chip .uip__title { margin: 0; font-size: 15px; }
